package com.southernstorm.noise.crypto

/**
 * Variant of New Hope that generates the public "a" value in constant time.
 *
 * The base [NewHope] class generates "a" in a way that is not constant-time,
 * which can be a problem in anonymity networks like Tor. This subclass sorts
 * the candidate coefficients with a fixed comparison network instead.
 *
 * ⚠ **Rien n'appelle cette classe dans Atom4Love**, pas plus que [NewHope].
 *
 * ⚠ Comme dans [NewHope], les `char[]` de l'amont sont ici des `IntArray` et
 * chaque `(char)` devient un `and 0xFFFF` — voir la note de classe de
 * [NewHope] pour le pourquoi.
 *
 * ⚠ Les 904 énoncés de [batcher84] n'ont pas été recopiés à la main : ils sont
 * convertis par script depuis le Java d'origine, et le script refuse toute
 * ligne qui s'écarterait du motif attendu. Une paire d'indices intervertie
 * dans un réseau de tri ne casse rien de visible — elle trie mal.
 */
open class NewHopeTor : NewHope() {

    override fun uniform(coeffs: IntArray, seed: ByteArray) {
        val state = LongArray(25)
        val nblocks = 16
        val buf = ByteArray(SHAKE128_RATE * nblocks)
        val x = IntArray(buf.size / 2)

        try {
            shake128_absorb(state, seed, 0, SEEDBYTES)
            do {
                shake128_squeezeblocks(buf, 0, nblocks, state)
                var i = buf.size - 2
                while (i >= 0) {
                    x[i / 2] = (
                        (buf[i].toInt() and 0xff) or ((buf[i + 1].toInt() and 0xff) shl 8)
                        ) and 0xFFFF
                    i -= 2
                }
            } while (discardtopoly(coeffs, x))
        } finally {
            state.fill(0)
            buf.fill(0)
            x.fill(0)
        }
    }

