        private fun discardtopoly(coeffs: IntArray, x: IntArray): Boolean {
            var r = 0

            for (i in 0 until 16) batcher84(x, i)

            // Check whether we're safe:
            for (i in 1008 until 1024) r = r or (61444 - x[i])
            // ⚠ Décalage ARITHMÉTIQUE : c'est le bit de signe qui dit qu'un
            // coefficient a débordé. Un `ushr` rendrait toujours faux.
            r = r shr 31
            if (r != 0) return true

            // If we are, copy coefficients to polynomial:
            for (i in 0 until PARAM_N) coeffs[i] = x[i]

            return false
        }

